-- Generated by vault-agent (WP124): a driving key of sat_account_customer_eff holds at most one
-- open relationship. Fails after batches were loaded out of order (README).
{%- set open_end = automate_dv.cast_date(automate_dv.cast_datetime(automate_dv.max_datetime(), as_string=true)) %}
with latest as (
    select *, row_number() over (partition by LINK_ACCOUNT_CUSTOMER_HK order by LOAD_DATETIME desc) as vault_agent_rank
    from {{ ref('sat_account_customer_eff') }}
), open_now as (
    select ACCOUNT_HK from latest
    where vault_agent_rank = 1 and {{ automate_dv.cast_date('EFFECTIVE_TO') }} = {{ open_end }}
)
select ACCOUNT_HK, count(*) as open_relationships
from open_now
group by ACCOUNT_HK
having count(*) > 1
